fn walk_query<'a>(m: &'a ast::Query, out: &mut dyn FnMut(NodeRef<'a>)) {
    if let Some(x) = &m.utility_stmt {
        out(x.to_ref());
    }
    for x in m.cte_list.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.rtable.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.rteperminfos.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.jointree {
        let x: &'a ast::FromExpr = x;
        out(NodeRef::FromExpr(x));
    }
    for x in m.merge_action_list.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.merge_join_condition {
        out(x.to_ref());
    }
    for x in m.target_list.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.on_conflict {
        let x: &'a ast::OnConflictExpr = x;
        out(NodeRef::OnConflictExpr(x));
    }
    for x in m.returning_list.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.group_clause.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.grouping_sets.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.having_qual {
        out(x.to_ref());
    }
    for x in m.window_clause.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.distinct_clause.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.sort_clause.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.limit_offset {
        out(x.to_ref());
    }
    if let Some(x) = &m.limit_count {
        out(x.to_ref());
    }
    for x in m.row_marks.iter().flatten() {
        out(x.to_ref());
    }
    if let Some(x) = &m.set_operations {
        out(x.to_ref());
    }
    for x in m.constraint_deps.iter().flatten() {
        out(x.to_ref());
    }
    for x in m.with_check_options.iter().flatten() {
        out(x.to_ref());
    }
}

